/* ---------- helpers ---------- */
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pad = n => String(n).padStart(2,'0');
const dayKey = d => d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate());
const today = () => dayKey(new Date());
const dayIdx = () => { const d = new Date(); return Math.floor(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()) / 86400000); };
const fmtDate = d => new Intl.DateTimeFormat('ru-RU',{weekday:'long', day:'numeric', month:'long'}).format(d);
const fmtDay = key => { const [y,m,dd] = key.split('-').map(Number); const d = new Date(y, m-1, dd); return key === today() ? 'Сегодня' : new Intl.DateTimeFormat('ru-RU',{day:'numeric', month:'long', weekday:'long'}).format(d); };
const fmtTime = ms => { const d = new Date(ms); return pad(d.getHours())+':'+pad(d.getMinutes()); };
const plural = (n, a, b, c) => { const m10 = n % 10, m100 = n % 100; if (m10 === 1 && m100 !== 11) return a; if (m10 >= 2 && m10 <= 4 && (m100 < 12 || m100 > 14)) return b; return c; };
const uid = () => 'e' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
const discLabel = arr => arr.slice().sort().map(n => DISC[n].n).join(' ');
const r1 = n => Math.round(n * 10) / 10;
const fmtPts = n => { const v = r1(n); return String(v).replace('.', ','); };

