      + '<div class="field"><span>Горизонт жизни</span><div class="stepper"><button data-act="tstep" data-id="life:-1" aria-label="Меньше">−</button><output>' + T.lifeYears + ' ' + plural(T.lifeYears, 'год', 'года', 'лет') + '</output><button data-act="tstep" data-id="life:1" aria-label="Больше">+</button></div></div>'
      + '<div class="field"><span>Бодрствование в сутки</span><div class="stepper"><button data-act="tstep" data-id="wake:-1" aria-label="Меньше">−</button><output>' + T.wakeHours + ' ч</output><button data-act="tstep" data-id="wake:1" aria-label="Больше">+</button></div></div>'
