    + '<div class="exp-head"><button class="exp-title" data-act="expopen" data-id="' + e.id + '">' + esc(e.title) + '<br><span class="exp-type ' + e.type + '">' + (e.type === 'avoid' ? 'отказ' : 'делать') + (e.target ? ', цель ' + e.target + ' ' + plural(e.target, 'день', 'дня', 'дней') : '') + '</span></button>'
