let expTick = null;
function startExpTicker(){
  if (expTick) return;
  expTick = setInterval(() => {
    const els = document.querySelectorAll('.exp-timer[data-exp]');
    if (!els.length) return;
    els.forEach(el => { const e = expById(el.dataset.exp); if (e) el.textContent = expTimerText(e); });
  }, 15000);
}

/* ---------- v3: xp, levels, badges ---------- */
const LEVEL_NAMES = ['Новичок у Портика','Слушатель','Ученик','Прокоптон','Упражняющийся','Внимательный','Хозяин впечатлений','Рассудительный','Стойкий','Умеренный','Справедливый','Мужественный','Аскет','Невозмутимый','Следующий фактам','Друг Сенеки','Ученик Эпиктета','Собеседник Марка','Гражданин мира','Хранитель цитадели','Смотрящий сверху','Спокойный в буре','Свободный от страстей','Знающий меру','Хозяин времени','Почти мудрец','Мудрец, по слухам','Мудрец, по мнению друзей','Мудрец, по мнению Сенеки','Феникс'];
const LEVELS = LEVEL_NAMES.map((n, i) => [i === 0 ? 0 : Math.round(40 * Math.pow(i, 1.7)), n]);
/* visits: the streak that burns if you skip a day */
const LS_VISITS = 'portik.v1.visits';
function visitDays(){ return (state.visits && Array.isArray(state.visits.days)) ? state.visits.days : []; }
function visitStreak(days){
  const set = new Set(days || visitDays()); const d = new Date(); let n = 0;
  if (!set.has(dayKey(d))) d.setDate(d.getDate() - 1);
  while (set.has(dayKey(d))){ n++; d.setDate(d.getDate() - 1); }
  return n;
}
function bestVisitStreak(){
  const days = visitDays().slice().sort(); let best = 0, cur = 0, prev = null;
  days.forEach(k => { const d = parseDate(k); if (prev && Math.round((d - prev) / 86400000) === 1) cur++; else cur = 1; best = Math.max(best, cur); prev = d; });
  return best;
}
function recordVisit(){
  const v = state.visits = (state.visits && typeof state.visits === 'object') ? state.visits : { days:[], best:0 };
  if (!Array.isArray(v.days)) v.days = [];
  const k = today();
  if (!v.days.includes(k)){
    const before = v.days.length ? visitStreak(v.days.concat(dayKey(new Date(Date.now() - 86400000)))) : 0;
    const prevLen = Number(v.last || 0);
    v.days.push(k); v.days.sort();
    const cutoff = new Date(); cutoff.setDate(cutoff.getDate() - 400); const ck = dayKey(cutoff);
    v.days = v.days.filter(d => d >= ck);
    const now = visitStreak(v.days);
    if (prevLen > 1 && now === 1) v.burned = prevLen; else v.burned = 0;
    v.last = now; v.best = Math.max(Number(v.best || 0), now, bestVisitStreak());
    lsSet(LS_VISITS, v);
    if (v.burned) setTimeout(() => toast('Серия из ' + v.burned + ' ' + plural(v.burned, 'дня', 'дней', 'дней') + ' сгорела. Начинаем заново, без драмы'), 600);
  }
}
function weekKey(ms){ const d = new Date(ms); const dow = (d.getDay() + 6) % 7; d.setDate(d.getDate() - dow); return dayKey(d); }
function xpData(){
  const parts = { morning:0, evening:0, exercise:0, rating:0, exp:0, words:0, books:0, time:0, visits:0, voyage:0 };
  const weeks = {};
  const add = (k, v, ms) => { parts[k] += v; if (ms){ const w = weekKey(ms); weeks[w] = (weeks[w] || 0) + v; } };
  state.entries.forEach(e => {
    if (e.kind === 'morning') add('morning', 10, e.createdAt);
    else if (e.kind === 'evening') add('evening', 15, e.createdAt);
    else if (e.kind === 'exercise') add('exercise', 10, e.createdAt);
    else if (e.kind === 'rating') add('rating', 3, e.createdAt);
  });
  state.exps.forEach(e => {
    Object.keys(e.days || {}).forEach(k => { if (e.days[k] === 'ok'){ const d = parseDate(k); add('exp', 5, d ? d.getTime() : 0); } });
    if (e.status === 'done') add('exp', 50, e.endedAt || Date.now());
  });
  state.dict.forEach(w => add('words', 2, w.addedAt));
  state.books.forEach(b => { const p = bookProgress(b); if (p > 0) add('books', Math.round(p / 5), b.openedAt || b.addedAt); });
  Object.keys(state.time.log || {}).forEach(k => { if (sumObj(state.time.log[k]) > 0){ const d = parseDate(k); add('time', 1, d ? d.getTime() : 0); } });
  visitDays().forEach(k => { const d = parseDate(k); add('visits', 2, d ? d.getTime() : 0); });
  voyage().visited.forEach(() => add('voyage', 3, 0));
  const total = Object.values(parts).reduce((a, b) => a + b, 0);
  let li = 0; for (let i = 0; i < LEVELS.length; i++) if (total >= LEVELS[i][0]) li = i;
  const next = LEVELS[li + 1] ? LEVELS[li + 1][0] : null;
  const base = LEVELS[li][0];
  return { total, parts, weeks, level: li + 1, name: LEVELS[li][1], next, frac: next ? (total - base) / (next - base) : 1 };
}
function levelRing(x, size){
  const r = 30, c = 2 * Math.PI * r, off = c * (1 - Math.min(1, x.frac));
  return '<svg class="ring" viewBox="0 0 72 72" role="img" aria-label="Уровень ' + x.level + '"><circle class="bg" cx="36" cy="36" r="' + r + '"/><circle class="fg" cx="36" cy="36" r="' + r + '" stroke-dasharray="' + c.toFixed(1) + '" stroke-dashoffset="' + off.toFixed(1) + '" transform="rotate(-90 36 36)"/><text x="36" y="45" text-anchor="middle">' + x.level + '</text></svg>';
}
function levelCard(){
  const x = xpData(), vs = visitStreak(), best = Math.max(bestVisitStreak(), Number((state.visits || {}).best || 0));
  return '<button class="card tap" data-act="progress"><div class="lvl">' + levelRing(x) + '<div><div class="lvl-name">' + esc(x.name) + '</div><div class="lvl-sub">' + x.total + ' XP, уровень ' + x.level + ' из ' + LEVELS.length + (x.next ? ', до следующего ' + (x.next - x.total) : ', потолок') + '</div><span class="xpbar"><i style="width:' + Math.round(x.frac * 100) + '%"></i></span><div class="lvl-foot"><span>серия ' + vs + ' ' + plural(vs, 'день', 'дня', 'дней') + (best > vs ? ', лучшая ' + best : '') + '</span><span>' + (vs > 0 ? 'сгорит, если пропустить день' : 'начинается сегодня') + '</span></div></div></div></button>';
}
const BADGES = [
  { id:'first', n:'Первый шаг', d:'Первая запись в дневнике', ok: () => state.entries.some(e => e.kind !== 'rating') },
  { id:'week', n:'Семь дней', d:'Неделя подряд в Портике', ok: () => Math.max(visitStreak(), bestVisitStreak()) >= 7 },
  { id:'month', n:'Месяц', d:'30 дней подряд в Портике', ok: () => Math.max(visitStreak(), bestVisitStreak()) >= 30 },
  { id:'hundred', n:'Сто дней', d:'100 дней подряд в Портике', ok: () => Math.max(visitStreak(), bestVisitStreak()) >= 100 },
  { id:'practice7', n:'Неделя практики', d:'7 дней подряд с записью в дневнике', ok: () => streak() >= 7 },
  { id:'judge', n:'Вечерний судья', d:'10 вечерних разборов', ok: () => state.entries.filter(e => e.kind === 'evening').length >= 10 },
  { id:'dawn', n:'Утренний страж', d:'10 утренних подготовок', ok: () => state.entries.filter(e => e.kind === 'morning').length >= 10 },
  { id:'faces', n:'Четыре грани', d:'Практика по всем граням добродетели', ok: () => { const p = practice(0); return VIRT.every(v => p.v[v.id] > 0); } },
  { id:'ascet', n:'Аскет', d:'Завершенный эксперимент', ok: () => state.exps.some(e => e.status === 'done') },
  { id:'iron', n:'Железная воля', d:'30 дней в зачет в одном эксперименте', ok: () => state.exps.some(e => expOkDays(e) >= 30) },
  { id:'words50', n:'Филолог', d:'50 слов в словаре', ok: () => state.dict.length >= 50 },
  { id:'words200', n:'Лексикон', d:'200 слов в словаре', ok: () => state.dict.length >= 200 },
  { id:'reader', n:'Читатель', d:'Дочитанная книга', ok: () => state.books.some(b => bookProgress(b) >= 99) },
  { id:'time7', n:'Учет времени', d:'7 дней отметок у пожирателей', ok: () => Object.keys(state.time.log || {}).filter(k => sumObj(state.time.log[k]) > 0).length >= 7 },
  { id:'mirror', n:'Самопознание', d:'4 самооценки добродетели', ok: () => state.entries.filter(e => e.kind === 'rating').length >= 4 },
  { id:'sailor', n:'Мореход', d:'10 пристаней на море философии', ok: () => voyage().visited.size >= 10 },
  { id:'circum', n:'Кругосветка', d:'Все пристани на море философии', ok: () => voyage().visited.size >= HARBORS.length - 1 },
  { id:'becker', n:'Следую фактам', d:'Все 6 упражнений Беккера', ok: () => EX.filter(x => x.src === 'becker').every(x => state.entries.some(e => e.exId === x.id)) },
  { id:'pigliucci', n:'Двенадцать', d:'Все 12 упражнений Пильюччи', ok: () => EX.filter(x => x.src === 'pigliucci' && x.id.startsWith('p-')).every(x => x.flow || state.entries.some(e => e.exId === x.id)) }
];
function barsSvg(values, labels, cls){
  const W = 360, H = 150, pad = 24, n = values.length; const max = Math.max(1, ...values);
  const bw = (W - pad * 2) / n, gap = Math.min(8, bw * .25);
  let s = '<svg class="bars-svg" viewBox="0 0 ' + W + ' ' + H + '" role="img" aria-label="Диаграмма по неделям">';
  s += '<line class="axis" x1="' + pad + '" y1="' + (H - 22) + '" x2="' + (W - pad) + '" y2="' + (H - 22) + '"/>';
  values.forEach((v, i) => {
    const h = Math.round((H - 50) * v / max), x = pad + i * bw + gap / 2, y = H - 22 - h;
    s += '<rect class="bar ' + (cls || '') + '" x="' + x.toFixed(1) + '" y="' + y + '" width="' + (bw - gap).toFixed(1) + '" height="' + h + '" rx="3"/>';
    if (v) s += '<text class="val" x="' + (x + (bw - gap) / 2).toFixed(1) + '" y="' + (y - 4) + '" text-anchor="middle">' + v + '</text>';
    if (labels[i]) s += '<text class="lab" x="' + (x + (bw - gap) / 2).toFixed(1) + '" y="' + (H - 8) + '" text-anchor="middle">' + esc(labels[i]) + '</text>';
  });
  return s + '</svg>';
}
function lastWeeks(n){ const out = []; const d = new Date(); const dow = (d.getDay() + 6) % 7; d.setDate(d.getDate() - dow); for (let i = n - 1; i >= 0; i--){ const w = new Date(d); w.setDate(d.getDate() - i * 7); out.push(dayKey(w)); } return out; }
function renderProgress(){
  const x = xpData();
  const wk = lastWeeks(12);
  const labels = wk.map((k, i) => (i % 2 === 0 || i === wk.length - 1) ? k.slice(8, 10) + '.' + k.slice(5, 7) : '');
  const xpVals = wk.map(k => x.weeks[k] || 0);
  const expVals = wk.map(k => state.exps.reduce((a, e) => a + Object.keys(e.days || {}).filter(d => e.days[d] === 'ok' && weekKey(parseDate(d).getTime()) === k).length, 0));
  const names = { visits:'Дни в Портике', voyage:'Пристани на море философии', morning:'Утренние подготовки', evening:'Вечерние разборы', exercise:'Упражнения', rating:'Самооценки', exp:'Эксперименты', words:'Слова в словаре', books:'Чтение', time:'Учет времени' };
  const earned = BADGES.filter(b => b.ok()), locked = BADGES.filter(b => !b.ok());
  const vs = visitStreak(), best = Math.max(bestVisitStreak(), Number((state.visits || {}).best || 0)), ps = streak(), vd = visitDays().length;
  const lvlRows = state.showLevels ? LEVELS : LEVELS.filter((l, i) => Math.abs(i + 1 - x.level) <= 2 || i === LEVELS.length - 1);
  return levelCard()
    + '<div class="stat4"><div><b>' + vs + '</b><span>' + plural(vs, 'день подряд', 'дня подряд', 'дней подряд') + '</span></div><div><b>' + best + '</b><span>лучшая серия</span></div><div><b>' + ps + '</b><span>' + plural(ps, 'день', 'дня', 'дней') + ' практики подряд</span></div><div><b>' + vd + '</b><span>' + plural(vd, 'день', 'дня', 'дней') + ' в Портике всего</span></div></div>'
    + '<p class="sec-note" style="margin-top:4px">Серия растет, пока заходишь каждый день, и сгорает, если пропустить хотя бы один. Опыт считается из того, что уже есть в дневнике, экспериментах, словаре и чтении. Ничего отдельно не копится, нечему потеряться.</p>'
    + '<h2 class="sec-title">Опыт по неделям</h2>' + barsSvg(xpVals, labels, '')
    + '<h2 class="sec-title" style="margin-top:18px">Эксперименты: дни в зачет</h2>' + barsSvg(expVals, labels, 'exp')
    + '<h2 class="sec-title" style="margin-top:18px">Из чего сложилось</h2><ul class="xp-list">' + Object.keys(names).map(k => '<li><span>' + names[k] + '</span><b>' + x.parts[k] + ' XP</b></li>').join('') + '</ul>'
    + '<h2 class="sec-title">Достижения</h2><p class="sec-note">' + earned.length + ' из ' + BADGES.length + '</p>'
    + '<div class="badges">' + earned.map(b => '<div class="badge"><div class="bi">' + roman(BADGES.indexOf(b) + 1) + '</div><span class="bn">' + esc(b.n) + '</span><span class="bd">' + esc(b.d) + '</span></div>').join('') + locked.map(b => '<div class="badge locked"><div class="bi">' + roman(BADGES.indexOf(b) + 1) + '</div><span class="bn">' + esc(b.n) + '</span><span class="bd">' + esc(b.d) + '</span></div>').join('') + '</div>'
    + '<h2 class="sec-title">Уровни</h2><p class="sec-note">' + LEVELS.length + ' уровней, от новичка до феникса: Сенека писал, что мудрец рождается раз в пятьсот лет, как феникс.</p><ul class="xp-list">' + lvlRows.map(l => { const i = LEVELS.indexOf(l); return '<li' + (i + 1 === x.level ? ' style="color:var(--ink);font-weight:600"' : '') + '><span>' + (i + 1) + '. ' + l[1] + '</span><b>' + l[0] + ' XP</b></li>'; }).join('') + '</ul>'
    + '<button class="btn ghost small" data-act="levelsall">' + (state.showLevels ? 'Скрыть' : 'Показать все уровни') + '</button><div class="spacer"></div>';
}
function roman(n){ const m = [[10,'X'],[9,'IX'],[5,'V'],[4,'IV'],[1,'I']]; let s = ''; for (const [v, r] of m){ while (n >= v){ s += r; n -= v; } } return s; }

/* ---------- v3: home ---------- */
const HOME_WIDGETS = [
  { id:'level', name:'Уровень и серия' }, { id:'quote', name:'Цитата дня' }, { id:'rituals', name:'Утро и вечер' }, { id:'exercise', name:'Упражнение дня' },
  { id:'experiments', name:'Эксперименты' }, { id:'time', name:'Время' }, { id:'weak', name:'Слабая грань' }, { id:'principle', name:'Принцип дня' },
  { id:'reading', name:'Продолжить чтение' }, { id:'word', name:'Слово из словаря' }
];
function homeConf(){
  const c = state.home || {};
  const order = Array.isArray(c.order) ? c.order.filter(id => HOME_WIDGETS.some(w => w.id === id)) : [];
  HOME_WIDGETS.forEach(w => { if (!order.includes(w.id)) order.push(w.id); });
  return { order, off: new Set(Array.isArray(c.off) ? c.off : []) };
}
function saveHome(conf){ state.home = { order: conf.order, off: [...conf.off] }; lsSet(LS_HOME, state.home); }
