const LS_THEME = 'portik.v1.theme';
function applyTheme(){
  const t = APP_THEMES.some(x => x.id === state.theme) ? state.theme : 'auto';
  const root = document.documentElement;
  if (t === 'auto') root.removeAttribute('data-theme'); else root.setAttribute('data-theme', t);
  const th = APP_THEMES.find(x => x.id === t);
  document.querySelectorAll('meta[name="theme-color"]').forEach(m => { m.setAttribute('content', t === 'auto' ? (m.getAttribute('media') && m.getAttribute('media').includes('dark') ? '#000000' : '#F5F5F2') : th.paper); });
}
function themeGridHtml(){
  const groups = [...new Set(APP_THEMES.map(t => t.group))];
  return groups.map(g => '<p class="theme-group">' + esc(g) + '</p><div class="theme-grid">' + APP_THEMES.filter(t => t.group === g).map(t => {
    const paper = t.id === 'auto' ? 'var(--paper)' : t.paper, text = t.id === 'auto' ? 'var(--text)' : t.text;
    return '<button class="tsw" data-act="theme" data-id="' + t.id + '" aria-pressed="' + (state.theme === t.id) + '" style="background:' + paper + ';color:' + text + '"><b>Аа</b><span>' + esc(t.name) + '</span><span class="dots">' + t.v.map(cl => '<i style="background:' + cl + '"></i>').join('') + '</span></button>';
  }).join('') + '</div>').join('');
}
