function renderPractice(){
  const srcChips = [['all','Все']].concat(Object.keys(SRC).map(k => [k, SRC[k].name]));
  const list = EX.filter(e => (state.src === 'all' || e.src === state.src) && (state.disc.size === 0 || e.disc.some(d => state.disc.has(d))));
  let html = '<p class=\"sec-note\">Античные упражнения, упражнения Пильюччи и практики по мотивам «Нового стоицизма» Беккера.</p>'
    + '<div class="chips" role="group" aria-label="Источник">'+srcChips.map(([k,l]) => '<button class="chip" data-act="src" data-id="'+k+'" aria-pressed="'+(state.src===k)+'">'+esc(l)+'</button>').join('')+'</div>'
    + '<div class="chips" role="group" aria-label="Дисциплина">'+[1,2,3].map(n => '<button class="chip" data-act="disc" data-id="'+n+'" aria-pressed="'+state.disc.has(n)+'"><span class="n">'+DISC[n].n+'</span>'+DISC[n].name+'</button>').join('')+'</div>';
  if (!list.length) return html + '<p class="empty">Под эти фильтры ничего не подходит. Сними один из них.</p>';
  Object.keys(SRC).forEach(k => {
    const g = list.filter(e => e.src === k);
    if (!g.length) return;
    html += '<section class="group"><h3>'+esc(SRC[k].title)+'</h3><p class="group-note">'+esc(SRC[k].note)+'</p><div>'+g.map(exRow).join('')+'</div></section>';
  });
  return html;
}

function renderVirtue(){
  const p = practice(state.vWindow);
  const rating = latestRating();
  const maxV = Math.max(0, ...VIRT.map(v => p.v[v.id]));
  let chart = '';
  if (state.vMode === 'virtues'){
    const axes = VIRT.map(v => ({ label: v.name, cls: 'vc-'+v.id, sub: fmtPts(p.v[v.id]) + (rating ? ', оценка ' + rating.ratings[v.id] : '') }));
    const layers = [];
    if (maxV > 0) layers.push({ cls:'lp', dots:true, values: VIRT.map(v => p.v[v.id] / maxV) });
    if (rating) layers.push({ cls:'lr', values: VIRT.map(v => (rating.ratings[v.id] || 0) / 10) });
    chart = radar(axes, layers, { w:360, h:300, r:96, labels:true, sideBelow:true, labelAt:1.0, aria:'Паутина четырех добродетелей' });
  } else {
    const axes = SUBS.map(s => ({ label: s.short, cls: 'vc-'+SUB2V[s.id] }));
    const maxS = Math.max(0, ...SUBS.map(s => p.sub[s.id]));
    const layers = maxS > 0 ? [{ cls:'lp', dots:true, values: SUBS.map(s => p.sub[s.id] / maxS) }] : [];
    let idx = 0; const wedges = [];
    VIRT.forEach(v => { wedges.push({ from: idx, to: idx + v.sub.length - 1, cls: 'vc-'+v.id }); idx += v.sub.length; });
    chart = radar(axes, layers, { w:360, h:320, r:104, labels:true, small:true, labelAt:1.08, wedges, dotR:3.2, aria:'Паутина составляющих добродетели' });
  }
  let insight = '';
  if (p.total > 0){
    if (state.vMode === 'virtues'){
      const sorted = VIRT.slice().sort((a, b) => p.v[b.id] - p.v[a.id]);
      insight = '<p class="insight">Сильнее всего: <b class="tx-'+sorted[0].id+'">'+esc(sorted[0].name)+'</b>. Слабее всего: <b class="tx-'+sorted[3].id+'">'+esc(sorted[3].name)+'</b>.</p>';
    } else {
      const sorted = SUBS.slice().sort((a, b) => p.sub[b.id] - p.sub[a.id]);
      const zero = sorted.filter(s => p.sub[s.id] === 0);
      const weak = (zero.length ? zero : sorted.slice(-3)).slice(0, 3);
      insight = '<p class="insight">Сильнее всего: '+sorted.slice(0, 3).map(s => '<b class="tx-'+SUB2V[s.id]+'">'+esc(s.name)+'</b>').join(', ')+'. '+(zero.length ? 'Пока не тренировал: ' : 'Слабее всего: ')+weak.map(s => '<b class="tx-'+SUB2V[s.id]+'">'+esc(s.name)+'</b>').join(', ')+'.</p>';
    }
  }
  const bars = VIRT.map(v => {
    const share = p.total ? Math.round(p.v[v.id] / p.total * 100) : 0;
    return '<button class="bar-row" data-act="virtue" data-id="'+v.id+'"><span class="bar-name"><span class="sw bg-'+v.id+'"></span>'+esc(v.name)+'</span><span class="bar-track"><span class="bar-fill bg-'+v.id+'" style="width:'+share+'%"></span></span><span class="bar-val">'+share+'%</span></button>';
  }).join('');
  return '<p class=\"sec-note\">Для стоиков добродетель одна: верное отношение ко всему. У нее четыре грани и восемнадцать составляющих, по Арию Дидиму. Беккер сохраняет это единство и понимает добродетель как совершенство способности действовать.</p>'
    + '<section class="panel" aria-label="Развитие добродетелей">'
    +   '<div class="panel-head"><div class="seg" role="group" aria-label="Детализация"><button data-act="vmode" data-id="virtues" aria-pressed="'+(state.vMode==='virtues')+'">Грани</button><button data-act="vmode" data-id="parts" aria-pressed="'+(state.vMode==='parts')+'">Составляющие</button></div>'
    +   '<div class="seg" role="group" aria-label="Период"><button data-act="vwin" data-id="30" aria-pressed="'+(state.vWindow===30)+'">30 дней</button><button data-act="vwin" data-id="0" aria-pressed="'+(state.vWindow===0)+'">Все время</button></div></div>'
    +   chart
    +   (p.total === 0 ? '<p class="radar-empty">Паутина заполнится, когда в дневнике появятся упражнения, утренние и вечерние записи.</p>' : '')
    +   '<div class="legend"><span><i></i>Практика: относительно самой сильной '+(state.vMode==='virtues'?'грани':'составляющей')+'</span>'+(state.vMode==='virtues' ? (rating ? '<span><i class="r"></i>Самооценка от '+esc(fmtDay(rating.day).toLowerCase())+'</span>' : '') : '')+'</div>'
    +   insight
    +   '<div class="bars">'+bars+'</div>'
    +   '<div class="panel-foot"><span class="fine">Каждое упражнение тренирует свои составляющие. Утром выбранная добродетель тоже идет в зачет.</span><button class="btn primary small" data-act="rate">Оценить себя</button></div>'
    + '</section>'
    + '<h2 class="sec-title">Колесо добродетели</h2><p class="sec-note">Нажми на грань или составляющую, чтобы увидеть, что она значит и какие упражнения ее развивают. Чем насыщеннее цвет, тем больше практики.</p>'
    + wheel(p)
    + '<div class="vgroups">'+VIRT.map(v => '<div class="vgroup"><button class="vgroup-head" data-act="virtue" data-id="'+v.id+'"><span class="sw bg-'+v.id+'"></span>'+esc(v.name)+' <span class="doc-term" style="font-size:15px">'+esc(v.gr)+'</span></button><div>'+v.sub.map(s => svChip(s.id)).join('')+'</div></div>').join('')+'</div>';
}

